/**
 * BrainX V5 Auto-Inject Hook Handler
 *
 * Runs on agent:bootstrap — queries PostgreSQL for hot/warm memories
 * and injects them into the agent's MEMORY.md + BRAINX_CONTEXT.md.
 */

import { createRequire } from "module";
import fs from "node:fs/promises";
import path from "node:path";
import { execFile } from "node:child_process";

const BRAINX_DIR = "/home/clawd/.openclaw/skills/brainx-v5";
const brainxRequire = createRequire(path.join(BRAINX_DIR, "index.js"));

// ─── Agent profiles for context-aware injection ────────────────

import { readFileSync } from "node:fs";

let agentProfiles = {};
try {
  const raw = readFileSync(path.join(BRAINX_DIR, 'hook', 'agent-profiles.json'), 'utf-8');
  agentProfiles = JSON.parse(raw);
} catch {
  // No profiles file — all agents get default (unfiltered) injection
}

// Section markers for MEMORY.md — content between these is replaced each run
const BRAINX_START = "<!-- BRAINX:START -->";
const BRAINX_END = "<!-- BRAINX:END -->";

// ─── Env loading ───────────────────────────────────────────────

function loadEnv() {
  try {
    const dotenv = brainxRequire("dotenv");
    dotenv.config({ path: path.join(BRAINX_DIR, ".env"), quiet: true });
  } catch {}
}

// ─── Singleton pool ────────────────────────────────────────────

let _pool = null;
let _poolUrl = null;

function getPool(dbUrl) {
  if (_pool && _poolUrl === dbUrl) return _pool;
  if (_pool) { _pool.end().catch(() => {}); }
  try {
    const { Pool } = brainxRequire("pg");
    _pool = new Pool({ connectionString: dbUrl, max: 3, idleTimeoutMillis: 30000 });
    _poolUrl = dbUrl;
    _pool.on("error", (err) => {
      console.error("[brainx-inject] Pool background error:", err.message);
      _pool = null;
      _poolUrl = null;
    });
    return _pool;
  } catch (err) {
    console.error("[brainx-inject] Failed to create pool:", err.message);
    _pool = null;
    _poolUrl = null;
    throw err;
  }
}

// ─── Helpers ───────────────────────────────────────────────────

function extractAgentId(sessionKey) {
  if (!sessionKey) return "unknown";
  const parts = sessionKey.split(":");
  return parts.length >= 2 ? parts[1] : "unknown";
}

function ts() {
  return new Date().toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
}

function truncate(str, max = 150) {
  if (!str || str.length <= max) return str || "";
  return str.slice(0, max - 3) + "...";
}

// ─── Retry helpers ─────────────────────────────────────────────

const MAX_RETRIES = 3;
const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 5000;

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function calculateDelay(attempt) {
  const exponential = BASE_DELAY_MS * Math.pow(2, attempt);
  const jitter = Math.random() * 500;
  return Math.min(exponential + jitter, MAX_DELAY_MS);
}

async function withRetry(operation, context = "operation") {
  let lastError;
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      return await operation();
    } catch (err) {
      lastError = err;
      const isRetryable = err.code === 'ECONNREFUSED' || 
                          err.code === 'ETIMEDOUT' ||
                          err.code === 'ECONNRESET' ||
                          err.message?.includes('connection') ||
                          err.message?.includes('timeout');

      if (!isRetryable || attempt >= MAX_RETRIES - 1) {
        throw err;
      }

      const delay = calculateDelay(attempt);
      console.log(`[brainx-inject] ${context} failed (attempt ${attempt + 1}/${MAX_RETRIES}), retrying in ${Math.round(delay)}ms...`);
      await sleep(delay);
    }
  }
  throw lastError;
}

// ─── DB queries (with retry wrapper) ───────────────────────────

async function queryTopMemories(pool, { limit = 8, minImportance = 5, agentName = null }) {
  // Split into own-agent + cross-agent slots to ensure visibility across agents
  const crossSlots = Math.max(2, Math.floor(limit * 0.3));  // ~30% for other agents
  const ownSlots = limit - crossSlots;

  return withRetry(async () => {
    // 1. Own agent memories (or global if no agent)
    const ownFilter = agentName
      ? `AND (agent = $3 OR agent IS NULL)`
      : '';
    const ownParams = agentName
      ? [minImportance, ownSlots, agentName]
      : [minImportance, ownSlots];
    const { rows: ownRows } = await pool.query(
      `SELECT content, tier, importance, type, agent, context
       FROM brainx_memories
       WHERE tier IN ('hot', 'warm')
         AND importance >= $1
         AND superseded_by IS NULL
         ${ownFilter}
       ORDER BY importance DESC, last_seen DESC NULLS LAST, created_at DESC
       LIMIT $2`,
      ownParams
    );

    // 2. Cross-agent memories (from OTHER agents, prioritizing cross-agent tagged)
    const crossFilter = agentName
      ? `AND agent IS DISTINCT FROM $3 AND agent IS NOT NULL`
      : '';
    const crossParams = agentName
      ? [minImportance, crossSlots, agentName]
      : [minImportance, crossSlots];
    const { rows: crossRows } = await pool.query(
      `SELECT content, tier, importance, type, agent, context
       FROM brainx_memories
       WHERE tier IN ('hot', 'warm')
         AND importance >= $1
         AND superseded_by IS NULL
         ${crossFilter}
       ORDER BY
         CASE WHEN 'cross-agent' = ANY(tags) THEN 1 ELSE 0 END DESC,
         importance DESC, last_seen DESC NULLS LAST, created_at DESC
       LIMIT $2`,
      crossParams
    );

    return [...ownRows, ...crossRows];
  }, "queryTopMemories");
}

async function queryAgentMemories(
  pool,
  agentName,
  { limit = 5, minImportance = 5 }
) {
  return withRetry(async () => {
    const { rows } = await pool.query(
      `SELECT content, tier, importance, type, context
       FROM brainx_memories
       WHERE agent = $1
         AND importance >= $2
         AND superseded_by IS NULL
       ORDER BY importance DESC, last_seen DESC NULLS LAST
       LIMIT $3`,
      [agentName, minImportance, limit]
    );
    return rows;
  }, "queryAgentMemories");
}

async function queryByType(pool, type, { limit = 10, minImportance = 5 }) {
  return withRetry(async () => {
    const { rows } = await pool.query(
      `SELECT content, tier, importance, type, agent, context
       FROM brainx_memories
       WHERE type = $1
         AND tier IN ('hot', 'warm')
         AND importance >= $2
         AND superseded_by IS NULL
       ORDER BY importance DESC, last_seen DESC NULLS LAST
       LIMIT $3`,
      [type, minImportance, limit]
    );
    return rows;
  }, "queryByType");
}

async function queryFacts(pool, { limit = 25 }) {
  return withRetry(async () => {
    const { rows } = await pool.query(
      `SELECT content, tier, importance, context, tags::text AS tags
       FROM brainx_memories
       WHERE type = 'fact'
         AND superseded_by IS NULL
         AND tier IN ('hot', 'warm')
       ORDER BY importance DESC, last_seen DESC NULLS LAST
       LIMIT $1`,
      [limit]
    );
    return rows;
  }, "queryFacts");
}

// ─── Agent-aware query (uses agent-profiles.json) ──────────────

function getAgentProfile(agentName) {
  return agentProfiles[agentName] || null;
}

async function queryAgentAwareMemories(pool, agentName, { limit = 8, minImportance = 5 }) {
  const profile = getAgentProfile(agentName);

  // No profile → fall back to default top memories with cross-agent slots
  if (!profile || (profile.contexts.length === 0 && profile.excludeTypes.length === 0 && profile.boostTypes.length === 0)) {
    return queryTopMemories(pool, { limit, minImportance, agentName });
  }

  // Split into own-agent + cross-agent slots (same strategy as queryTopMemories)
  const crossSlots = Math.max(2, Math.floor(limit * 0.3));
  const ownSlots = limit - crossSlots;

  return withRetry(async () => {
    // Build shared clauses from profile
    let excludeClause = '';
    const sharedParams = [];
    let paramIdx = 3; // $1=minImportance, $2=limit

    if (profile.excludeTypes.length > 0) {
      excludeClause = ` AND type NOT IN (${profile.excludeTypes.map(() => `$${paramIdx++}`).join(',')})`;
      sharedParams.push(...profile.excludeTypes);
    }

    let contextBoostExpr = '0';
    if (profile.contexts.length > 0) {
      const contextPlaceholders = profile.contexts.map(() => `$${paramIdx++}`).join(',');
      sharedParams.push(...profile.contexts);
      contextBoostExpr = `CASE WHEN context IN (${contextPlaceholders}) THEN 2 ELSE 0 END`;
    }

    let boostTypeExpr = '0';
    if (profile.boostTypes.length > 0) {
      const boostPlaceholders = profile.boostTypes.map(() => `$${paramIdx++}`).join(',');
      sharedParams.push(...profile.boostTypes);
      boostTypeExpr = `CASE WHEN type IN (${boostPlaceholders}) THEN 1 ELSE 0 END`;
    }

    // 1. Own-agent memories (agent = agentName OR agent IS NULL)
    const ownAgentParam = paramIdx++;
    const ownParams = [minImportance, ownSlots, ...sharedParams, agentName];
    const ownSql = `SELECT content, tier, importance, type, agent, context
       FROM brainx_memories
       WHERE tier IN ('hot', 'warm')
         AND importance >= $1
         AND superseded_by IS NULL
         AND (agent = $${ownAgentParam} OR agent IS NULL)
         ${excludeClause}
       ORDER BY (${contextBoostExpr} + ${boostTypeExpr}) DESC,
                importance DESC,
                last_seen DESC NULLS LAST,
                created_at DESC
       LIMIT $2`;
    const { rows: ownRows } = await pool.query(ownSql, ownParams);

    // 2. Cross-agent memories (from other agents)
    // Reset paramIdx for cross query
    let crossParamIdx = 3;
    const crossSharedParams = [];
    let crossExcludeClause = '';
    if (profile.excludeTypes.length > 0) {
      crossExcludeClause = ` AND type NOT IN (${profile.excludeTypes.map(() => `$${crossParamIdx++}`).join(',')})`;
      crossSharedParams.push(...profile.excludeTypes);
    }
    let crossContextBoost = '0';
    if (profile.contexts.length > 0) {
      const cp = profile.contexts.map(() => `$${crossParamIdx++}`).join(',');
      crossSharedParams.push(...profile.contexts);
      crossContextBoost = `CASE WHEN context IN (${cp}) THEN 2 ELSE 0 END`;
    }
    let crossBoostType = '0';
    if (profile.boostTypes.length > 0) {
      const bp = profile.boostTypes.map(() => `$${crossParamIdx++}`).join(',');
      crossSharedParams.push(...profile.boostTypes);
      crossBoostType = `CASE WHEN type IN (${bp}) THEN 1 ELSE 0 END`;
    }
    const crossAgentParam = crossParamIdx++;
    const crossParams = [minImportance, crossSlots, ...crossSharedParams, agentName];
    const crossSql = `SELECT content, tier, importance, type, agent, context
       FROM brainx_memories
       WHERE tier IN ('hot', 'warm')
         AND importance >= $1
         AND superseded_by IS NULL
         AND agent IS DISTINCT FROM $${crossAgentParam} AND agent IS NOT NULL
         ${crossExcludeClause}
       ORDER BY
         CASE WHEN 'cross-agent' = ANY(tags) THEN 1 ELSE 0 END DESC,
         (${crossContextBoost} + ${crossBoostType}) DESC,
         importance DESC,
         last_seen DESC NULLS LAST,
         created_at DESC
       LIMIT $2`;
    const { rows: crossRows } = await pool.query(crossSql, crossParams);

    return [...ownRows, ...crossRows];
  }, "queryAgentAwareMemories");
}

// ─── Formatting ────────────────────────────────────────────────

function formatMemoryLine(m, maxLen = 150) {
  const meta = `[${m.tier}/imp:${m.importance}]`;
  return `- **${meta}** ${truncate(m.content, maxLen)}`;
}

function formatMemoryBlock(m) {
  const parts = [`[tier:${m.tier} imp:${m.importance} type:${m.type}`];
  if (m.agent) parts[0] += ` agent:${m.agent}`;
  if (m.context) parts[0] += ` ctx:${m.context}`;
  parts[0] += "]";
  parts.push(truncate(m.content, 2000));
  return parts.join("\n");
}

// ─── MEMORY.md injection ──────────────────────────────────────

function buildMemorySection(agentName, timestamp, teamMems, ownMems) {
  const lines = [BRAINX_START, "", "## BrainX Context (Auto-Injected)", ""];
  lines.push(`**Agent:** ${agentName} | **Updated:** ${timestamp}`);
  lines.push("");

  if (teamMems.length > 0) {
    // Split team memories: own-agent vs cross-agent for balanced display
    const ownTeam = teamMems.filter(m => m.agent === agentName || !m.agent);
    const crossTeam = teamMems.filter(m => m.agent && m.agent !== agentName);

    lines.push("### Top Memories");
    for (const m of ownTeam.slice(0, 5)) {
      lines.push(formatMemoryLine(m));
    }
    lines.push("");

    if (crossTeam.length > 0) {
      lines.push("### Cross-Agent Intel");
      for (const m of crossTeam.slice(0, 3)) {
        lines.push(`- **[${m.agent}/${m.tier}/imp:${m.importance}]** ${(m.content || '').slice(0, 120)}...`);
      }
      lines.push("");
    }
  }

  if (ownMems.length > 0) {
    lines.push(`### My Memories (${agentName})`);
    for (const m of ownMems.slice(0, 4)) {
      lines.push(formatMemoryLine(m));
    }
    lines.push("");
  }

  if (teamMems.length === 0 && ownMems.length === 0) {
    lines.push("*No hot/warm memories with importance >= 5.*");
    lines.push("");
  }

  lines.push(
    `> Full context: \`cat BRAINX_CONTEXT.md\` | Topics: \`cat brainx-topics/<topic>.md\``
  );
  lines.push("", BRAINX_END);
  return lines.join("\n");
}

async function updateMemoryMd(workspaceDir, section) {
  const memPath = path.join(workspaceDir, "MEMORY.md");
  let content = "";
  try {
    content = await fs.readFile(memPath, "utf-8");
  } catch {
    // File doesn't exist — will create with just the section
  }

  // Use lastIndexOf: MEMORY.md templates may reference the markers in
  // instructional text — the real injection block is always the last occurrence.
  const startIdx = content.lastIndexOf(BRAINX_START);
  const endIdx = content.lastIndexOf(BRAINX_END);

  if (startIdx !== -1 && endIdx !== -1) {
    // Replace existing section
    content =
      content.slice(0, startIdx) +
      section +
      content.slice(endIdx + BRAINX_END.length);
  } else {
    // Append
    content = content.trimEnd() + "\n\n" + section + "\n";
  }

  await fs.writeFile(memPath, content, "utf-8");
}

// ─── BRAINX_CONTEXT.md + topic files (backward compat) ───────

async function writeTopicFile(dir, filename, title, memories, timestamp) {
  const filePath = path.join(dir, filename);
  if (memories.length === 0) {
    await fs.writeFile(filePath, `# ${title} — None found\n`, "utf-8");
    return 0;
  }
  const lines = [`# ${title}`, "", `**Updated:** ${timestamp}`, ""];
  for (const m of memories) {
    lines.push(formatMemoryBlock(m));
    lines.push("");
    lines.push("---");
    lines.push("");
  }
  await fs.writeFile(filePath, lines.join("\n"), "utf-8");
  return memories.length;
}

async function writeBrainxContext(
  workspaceDir,
  agentName,
  timestamp,
  counts,
  facts,
  ownMems
) {
  const topicsDir = path.join(workspaceDir, "brainx-topics");
  const contextPath = path.join(workspaceDir, "BRAINX_CONTEXT.md");

  // Compact index — always loaded
  const lines = [
    "# BrainX V5 Context (Auto-Injected)",
    "",
    `**Agent:** ${agentName} | **Updated:** ${timestamp}`,
    "**Mode:** Compact index — read topic files with `cat brainx-topics/<file>.md` when you need detail",
    "",
  ];

  // Facts summary
  lines.push(
    `## Facts (${counts.facts}) -> \`brainx-topics/facts.md\``
  );
  if (facts.length > 0) {
    for (const f of facts.slice(0, 5)) {
      lines.push(`  - [${f.tier}] ${truncate(f.content, 100)}`);
    }
  } else {
    lines.push("  *Empty*");
  }
  lines.push("");

  // Own memories summary
  lines.push(
    `## My memories (${counts.own}) -> \`brainx-topics/own.md\``
  );
  if (ownMems.length > 0) {
    for (const m of ownMems.slice(0, 3)) {
      lines.push(`  - ${truncate(m.content, 100)}`);
    }
  } else {
    lines.push("  *No own memories*");
  }
  lines.push("");

  // Topics directory table
  lines.push("## Topics");
  lines.push("");
  lines.push("| Topic | Items | File |");
  lines.push("|-------|-------|------|");
  lines.push(
    `| Decisions | ${counts.decisions} | \`brainx-topics/decisions.md\` |`
  );
  lines.push(
    `| Gotchas | ${counts.gotchas} | \`brainx-topics/gotchas.md\` |`
  );
  lines.push(
    `| Learnings | ${counts.learnings} | \`brainx-topics/learnings.md\` |`
  );
  lines.push(`| Team | ${counts.team} | \`brainx-topics/team.md\` |`);
  lines.push(`| Facts | ${counts.facts} | \`brainx-topics/facts.md\` |`);
  lines.push(`| Own | ${counts.own} | \`brainx-topics/own.md\` |`);
  lines.push("");

  lines.push("---");
  lines.push(
    '**Save fact:** `brainx add --type fact --tier hot --importance 8 --context "project:NAME" --content "..."`'
  );

  await fs.writeFile(contextPath, lines.join("\n") + "\n", "utf-8");
  return lines.join("\n").length;
}

// ─── Telemetry ─────────────────────────────────────────────────

async function logInjection(pool, agentName, ownCount, teamCount, totalChars) {
  try {
    await pool.query(
      `INSERT INTO brainx_pilot_log (agent, own_memories, team_memories, total_chars, injected_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [agentName, ownCount, teamCount, totalChars]
    );
  } catch {}
}

// ─── Main handler ──────────────────────────────────────────────

const handler = async (event) => {
  if (event.type !== "agent" || event.action !== "bootstrap") return;

  const t0 = Date.now();

  try {
    loadEnv();

    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      console.error("[brainx-inject] DATABASE_URL not set, skipping");
      return;
    }

    const workspaceDir = event.context?.workspaceDir;
    if (!workspaceDir) {
      console.error("[brainx-inject] No workspaceDir in event context, skipping");
      return;
    }

    // Extract agent ID from multiple sources (event context, session key, env)
    const agentName = event.agentId || event.agent || extractAgentId(event.sessionKey) || process.env.OPENCLAW_AGENT_ID || 'unknown';
    const timestamp = ts();

    const pool = getPool(dbUrl);

    {
      // Run all queries in parallel (team memories are now agent-aware)
      const [teamMems, ownMems, facts, decisions, learnings, gotchas] =
        await Promise.all([
          queryAgentAwareMemories(pool, agentName, { limit: 12, minImportance: 5 }),
          queryAgentMemories(pool, agentName, { limit: 5, minImportance: 5 }),
          queryFacts(pool, { limit: 25 }),
          queryByType(pool, "decision", { limit: 8, minImportance: 5 }),
          queryByType(pool, "learning", { limit: 8, minImportance: 5 }),
          queryByType(pool, "gotcha", { limit: 10, minImportance: 3 }),
        ]);

      // 1. Update MEMORY.md (primary injection path)
      const memSection = buildMemorySection(
        agentName,
        timestamp,
        teamMems,
        ownMems
      );
      await updateMemoryMd(workspaceDir, memSection);

      // 2. Write topic files (backward compat)
      const topicsDir = path.join(workspaceDir, "brainx-topics");
      await fs.mkdir(topicsDir, { recursive: true });

      const [, , , , ,] = await Promise.all([
        writeTopicFile(
          topicsDir,
          "facts.md",
          "Project Facts",
          facts,
          timestamp
        ),
        writeTopicFile(
          topicsDir,
          "decisions.md",
          "Decisions",
          decisions,
          timestamp
        ),
        writeTopicFile(
          topicsDir,
          "learnings.md",
          "Learnings & Insights",
          learnings,
          timestamp
        ),
        writeTopicFile(
          topicsDir,
          "team.md",
          "Team Knowledge (High Importance)",
          teamMems,
          timestamp
        ),
        writeTopicFile(
          topicsDir,
          "own.md",
          `Agent: ${agentName} — My Memories`,
          ownMems,
          timestamp
        ),
      ]);

      const counts = {
        facts: facts.length,
        decisions: decisions.length,
        learnings: learnings.length,
        team: teamMems.length,
        own: ownMems.length,
        gotchas: gotchas.length,
      };

      // 3. Write BRAINX_CONTEXT.md (compact index)
      const indexChars = await writeBrainxContext(
        workspaceDir,
        agentName,
        timestamp,
        counts,
        facts,
        ownMems
      );

      // Write gotchas topic with real data from DB
      await writeTopicFile(topicsDir, "gotchas.md", "Gotchas & Traps", gotchas, timestamp);

      // 4. Telemetry
      await logInjection(
        pool,
        agentName,
        ownMems.length,
        teamMems.length,
        memSection.length + indexChars
      );

      const elapsed = Date.now() - t0;
      console.log(
        `[brainx-inject] agent=${agentName} team=${teamMems.length} own=${ownMems.length} facts=${facts.length} decisions=${decisions.length} ${elapsed}ms`
      );
    }
  } catch (err) {
    const elapsed = Date.now() - t0;
    const errorMsg = err instanceof Error ? err.message : String(err);

    // Log error but don't crash the agent bootstrap
    console.error(`[brainx-inject] Failed after ${elapsed}ms: ${errorMsg}`);

    // Write a minimal fallback to MEMORY.md so the agent knows BrainX had issues
    try {
      const workspaceDir = event.context?.workspaceDir;
      if (workspaceDir) {
        const fallbackSection = `${BRAINX_START}\n\n## BrainX Context (Auto-Injected)\n\n**⚠️ BrainX injection failed:** ${errorMsg}\n\n> Run \`brainx health\` to check status\n\n${BRAINX_END}`;
        await updateMemoryMd(workspaceDir, fallbackSection);
      }
    } catch (fallbackErr) {
      // If even fallback fails, just log it
      console.error("[brainx-inject] Fallback write also failed:", fallbackErr);
    }
  }
};

export default handler;

{
  "name": "brainx-auto-inject-hook",
  "version": "1.0.0",
  "type": "module",
  "private": true
}

/**
 * BrainX Advisory System
 * Pre-action advisory that queries relevant memories before an agent executes a tool.
 */

const crypto = require('crypto');
const db = require('./db');
const rag = require('./openai-rag');

// ─── High-risk tool registry ──────────────────────────────────

const HIGH_RISK_TOOLS = new Set([
  'exec', 'deploy', 'railway', 'delete', 'rm', 'drop',
  'git push', 'git force-push', 'migration', 'cron',
  'message send', 'email send'
]);

/**
 * Check if a tool name is considered high-risk.
 * Matches exact tool names and also checks the first word (e.g. "git push" matches "git").
 * @param {string} tool
 * @returns {boolean}
 */
function isHighRisk(tool) {
  if (!tool) return false;
  return HIGH_RISK_TOOLS.has(tool) ||
    HIGH_RISK_TOOLS.has(tool.split(' ')[0]);
}

// Cooldown: don't spam same advice within this window (ms)
const ADVISORY_COOLDOWN_MS = parseInt(process.env.BRAINX_ADVISORY_COOLDOWN_MS || '300000', 10); // 5 min default

function makeAdvisoryId() {
  return `adv_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
}

/**
 * Build a search query string from action context for embedding similarity.
 */
function buildSearchQuery(actionContext) {
  const parts = [];
  if (actionContext.tool) parts.push(`tool:${actionContext.tool}`);
  if (actionContext.args) {
    try {
      const argsObj = typeof actionContext.args === 'string' ? JSON.parse(actionContext.args) : actionContext.args;
      // Include key arg values for better semantic match
      for (const [k, v] of Object.entries(argsObj)) {
        if (typeof v === 'string' && v.length < 200) parts.push(`${k}:${v}`);
      }
    } catch (_) {
      parts.push(String(actionContext.args));
    }
  }
  if (actionContext.project) parts.push(`project:${actionContext.project}`);
  if (actionContext.agent) parts.push(`agent:${actionContext.agent}`);
  return parts.join(' ');
}

/**
 * Check cooldown: was there a recent advisory for this agent+tool?
 */
async function isOnCooldown(agent, tool) {
  const cutoff = new Date(Date.now() - ADVISORY_COOLDOWN_MS);
  const res = await db.query(
    `SELECT id FROM brainx_advisories
     WHERE agent = $1 AND tool = $2 AND created_at > $3
     ORDER BY created_at DESC LIMIT 1`,
    [agent || 'unknown', tool, cutoff]
  );
  return res.rows.length > 0;
}

/**
 * Query memories relevant to the action context.
 */
async function queryRelevantMemories(searchQuery, limit = 5) {
  const rows = await rag.search(searchQuery, {
    limit,
    minSimilarity: 0.25,
    minImportance: 5,
    tierFilter: null, // we'll filter hot/warm in SQL
    contextFilter: null
  });

  // Filter to hot/warm and not superseded (search already excludes superseded)
  return rows.filter(r => r.tier === 'hot' || r.tier === 'warm');
}

/**
 * Query trajectories for similar problem→solution paths.
 */
async function queryTrajectories(searchQuery, limit = 3) {
  try {
    const embedding = await rag.embed(searchQuery);
    const res = await db.query(
      `SELECT id, context, problem, solution, outcome,
              1 - (embedding <=> $1::vector) AS similarity
       FROM brainx_trajectories
       WHERE outcome IN ('success', 'partial')
       ORDER BY similarity DESC
       LIMIT $2`,
      [JSON.stringify(embedding), limit]
    );
    return res.rows.filter(r => (r.similarity ?? 0) >= 0.25);
  } catch (_) {
    return [];
  }
}

/**
 * Query patterns for recurring issues related to the action.
 */
async function queryPatterns(tool, limit = 3) {
  try {
    const res = await db.query(
      `SELECT p.pattern_key, p.recurrence_count, p.impact_score, p.last_status,
              m.content AS representative_content, m.type AS memory_type
       FROM brainx_patterns p
       LEFT JOIN brainx_memories m ON m.id = p.representative_memory_id
       WHERE p.recurrence_count >= 2
         AND COALESCE(p.last_status, 'pending') NOT IN ('wont_fix')
       ORDER BY p.recurrence_count DESC, p.impact_score DESC
       LIMIT $1`,
      [limit]
    );
    return res.rows;
  } catch (_) {
    return [];
  }
}

/**
 * Format advisory results into readable text.
 */
function formatAdvisory(memories, trajectories, patterns) {
  const sections = [];
  let totalConfidence = 0;
  let count = 0;

  if (memories.length > 0) {
    const lines = memories.map(m => {
      const sim = (m.similarity ?? 0).toFixed(2);
      return `  • [${m.type}|sim:${sim}|imp:${m.importance}] ${m.content.slice(0, 200)}`;
    });
    sections.push(`📝 Relevant Memories (${memories.length}):\n${lines.join('\n')}`);
    totalConfidence += memories.reduce((s, m) => s + (m.similarity ?? 0), 0);
    count += memories.length;
  }

  if (trajectories.length > 0) {
    const lines = trajectories.map(t => {
      const sim = (t.similarity ?? 0).toFixed(2);
      return `  • [${t.outcome}|sim:${sim}] ${t.problem?.slice(0, 100) || 'N/A'} → ${t.solution?.slice(0, 100) || 'N/A'}`;
    });
    sections.push(`🔄 Similar Past Paths (${trajectories.length}):\n${lines.join('\n')}`);
    totalConfidence += trajectories.reduce((s, t) => s + (t.similarity ?? 0), 0);
    count += trajectories.length;
  }

  if (patterns.length > 0) {
    const lines = patterns.map(p =>
      `  • [×${p.recurrence_count}|impact:${(p.impact_score ?? 0).toFixed(1)}] ${p.representative_content?.slice(0, 150) || p.pattern_key}`
    );
    sections.push(`🔁 Recurring Patterns (${patterns.length}):\n${lines.join('\n')}`);
    // Patterns add a fixed confidence boost
    totalConfidence += patterns.length * 0.3;
    count += patterns.length;
  }

  const avgConfidence = count > 0 ? Math.min(totalConfidence / count, 1.0) : 0;
  const sourceIds = memories.map(m => m.id);

  return {
    text: sections.length > 0 ? sections.join('\n\n') : null,
    confidence: Number(avgConfidence.toFixed(3)),
    sourceIds,
    totalSources: count
  };
}

/**
 * Main advisory function.
 * @param {Object} actionContext - { tool, args, agent, project }
 * @returns {Object} { advisory_text, confidence, source_memory_ids, id, on_cooldown }
 */
async function getAdvisory(actionContext) {
  const { tool, args, agent, project } = actionContext;

  // Check cooldown
  if (await isOnCooldown(agent, tool)) {
    return {
      id: null,
      advisory_text: null,
      confidence: 0,
      source_memory_ids: [],
      on_cooldown: true
    };
  }

  const searchQuery = buildSearchQuery(actionContext);

  // Query all sources in parallel
  const [memories, trajectories, patterns] = await Promise.all([
    queryRelevantMemories(searchQuery),
    queryTrajectories(searchQuery),
    queryPatterns(tool)
  ]);

  const { text, confidence, sourceIds, totalSources } = formatAdvisory(memories, trajectories, patterns);

  if (!text) {
    return {
      id: null,
      advisory_text: null,
      confidence: 0,
      source_memory_ids: [],
      on_cooldown: false
    };
  }

  // Store the advisory
  const id = makeAdvisoryId();
  const actionContextJson = {
    tool,
    args: typeof args === 'string' ? (() => { try { return JSON.parse(args); } catch (_) { return args; } })() : args,
    agent,
    project
  };

  await db.query(
    `INSERT INTO brainx_advisories (id, agent, tool, action_context, advisory_text, source_memory_ids, confidence)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [id, agent || 'unknown', tool, JSON.stringify(actionContextJson), text, sourceIds, confidence]
  );

  return {
    id,
    advisory_text: text,
    confidence,
    source_memory_ids: sourceIds,
    on_cooldown: false
  };
}

/**
 * Record feedback on an advisory.
 */
async function advisoryFeedback(advisoryId, wasFollowed, outcome) {
  const res = await db.query(
    `UPDATE brainx_advisories
     SET was_followed = $2, outcome = $3
     WHERE id = $1
     RETURNING id, agent, tool, was_followed, outcome`,
    [advisoryId, wasFollowed, outcome || null]
  );
  if (res.rowCount === 0) throw new Error(`Advisory not found: ${advisoryId}`);
  return res.rows[0];
}

module.exports = { getAdvisory, advisoryFeedback, buildSearchQuery, formatAdvisory, isHighRisk, HIGH_RISK_TOOLS };

function parseBoolEnv(name, fallback) {
  const raw = process.env[name];
  if (raw === undefined) return fallback;
  const v = String(raw).trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
  if (['0', 'false', 'no', 'off'].includes(v)) return false;
  return fallback;
}

function getPhase2Config() {
  const allowlistContexts = (process.env.BRAINX_PII_SCRUB_ALLOWLIST_CONTEXTS || '')
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean);
  return {
    piiScrubEnabled: parseBoolEnv('BRAINX_PII_SCRUB_ENABLED', true),
    piiScrubReplacement: process.env.BRAINX_PII_SCRUB_REPLACEMENT || '[REDACTED]',
    piiScrubAllowlistContexts: allowlistContexts,
    dedupeSimThreshold: Number.parseFloat(process.env.BRAINX_DEDUPE_SIM_THRESHOLD || '0.92') || 0.92,
    dedupeRecentDays: Number.parseInt(process.env.BRAINX_DEDUPE_RECENT_DAYS || '30', 10) || 30
  };
}

const PII_PATTERNS = [
  { reason: 'email', regex: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi },
  { reason: 'phone', regex: /(?<!\w)(?:\+?1[\s.\-]?)?(?:\(?\d{3}\)?[\s.\-]?)?\d{3}[\s.\-]?\d{4}(?!\w)/g },
  { reason: 'openai_key', regex: /\bsk-[A-Za-z0-9]{16,}\b/g },
  { reason: 'github_token', regex: /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{20,}\b/g },
  { reason: 'github_pat', regex: /\bgithub_pat_[A-Za-z0-9_]{20,}\b/g },
  { reason: 'aws_access_key', regex: /\bAKIA[0-9A-Z]{16}\b/g },
  { reason: 'slack_token', regex: /\bxox(?:b|p|a|r|s)-[A-Za-z0-9-]{10,}\b/g },
  { reason: 'bearer_token', regex: /\bBearer\s+[A-Za-z0-9._\-]{16,}\b/gi },
  { reason: 'api_key_assignment', regex: /\b(?:api|access|secret)[_-]?key\s*[:=]\s*['"]?[A-Za-z0-9._\-]{12,}['"]?/gi },
  { reason: 'jwt_token', regex: /\beyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\b/g },
  { reason: 'private_key_block', regex: /-----BEGIN(?: RSA| EC| OPENSSH)? PRIVATE KEY-----[\s\S]*?-----END(?: RSA| EC| OPENSSH)? PRIVATE KEY-----/g },
  { reason: 'iban', regex: /\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b/g },
  { reason: 'credit_card', regex: /\b(?:\d[ -]*?){13,19}\b/g },
  { reason: 'ipv4', regex: /\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g },
  { reason: 'password_inline', regex: /(?:contraseña|password|passwd|pass|clave|secret)\s*(?:(?:es|is|actual|nueva|new|=|:)\s*){1,2}['"`]?[^\s'"`,]{4,}['"`]?/gi },
  { reason: 'password_quoted', regex: /(?:contraseña|password|passwd|clave)\s*[:=]\s*['"][^'"]{4,}['"]/gi },
];

function shouldScrubForContext(context, cfg = {}) {
  const enabled = cfg.piiScrubEnabled !== undefined ? !!cfg.piiScrubEnabled : true;
  if (!enabled) return false;
  const ctx = context == null ? '' : String(context).trim();
  if (!ctx) return true;
  const allow = new Set((cfg.piiScrubAllowlistContexts || []).map((v) => String(v).trim()).filter(Boolean));
  return !allow.has(ctx);
}

function scrubTextPII(text, opts = {}) {
  const input = text == null ? text : String(text);
  const enabled = opts.enabled !== undefined ? !!opts.enabled : true;
  const replacement = opts.replacement || '[REDACTED]';
  if (input == null || !enabled) {
    return { text: input, redacted: false, reasons: [] };
  }

  let out = input;
  const reasons = [];
  for (const { reason, regex } of PII_PATTERNS) {
    regex.lastIndex = 0;
    if (!regex.test(out)) continue;
    reasons.push(reason);
    regex.lastIndex = 0;
    out = out.replace(regex, replacement);
  }
  return { text: out, redacted: reasons.length > 0, reasons };
}

function mergeTagsWithMetadata(tags, meta = {}) {
  const input = Array.isArray(tags) ? tags.slice() : [];
  const seen = new Set(input.map(String));
  if (meta.redacted) {
    for (const tag of ['pii:redacted', ...(meta.reasons || []).map((r) => `pii:${r}`)]) {
      if (seen.has(tag)) continue;
      seen.add(tag);
      input.push(tag);
    }
  }
  return input;
}

function deriveMergePlan(existingRow, lifecycle, now) {
  const current = existingRow || null;
  const tsNow = now || new Date();
  if (!current) {
    return {
      found: false,
      finalId: null,
      finalRecurrence: Number(lifecycle.recurrence_count || 1),
      finalFirstSeen: lifecycle.first_seen || tsNow,
      finalLastSeen: lifecycle.last_seen || tsNow
    };
  }

  return {
    found: true,
    finalId: current.id,
    finalRecurrence: Math.max(
      Number(current.recurrence_count || 1) + 1,
      Number(lifecycle.recurrence_count || 0)
    ),
    finalFirstSeen: lifecycle.first_seen || current.first_seen || tsNow,
    finalLastSeen: lifecycle.last_seen || tsNow
  };
}

function cosineSimilarity(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    const x = Number(a[i]) || 0;
    const y = Number(b[i]) || 0;
    dot += x * y;
    na += x * x;
    nb += y * y;
  }
  if (!na || !nb) return 0;
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

module.exports = {
  getPhase2Config,
  shouldScrubForContext,
  scrubTextPII,
  mergeTagsWithMetadata,
  deriveMergePlan,
  cosineSimilarity
};

