#!/usr/bin/env node
/**
 * BrainX V5 — Context-Pack Builder (Phase 2.2)
 *
 * Generates weekly "context packs" that summarise hot/warm memories
 * grouped by context (agent:*, project:*).  Packs are compact markdown
 * blocks designed for efficient LLM injection (fewer tokens, more signal).
 *
 * Usage:
 *   node scripts/context-pack-builder.js [--days N] [--dry-run] [--verbose]
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ── Bootstrap env + DB ────────────────────────────────────────────────
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });
const db = require('../lib/db');

// ── CLI args ──────────────────────────────────────────────────────────
const args   = process.argv.slice(2);
const DAYS   = (() => { const i = args.indexOf('--days'); return i !== -1 && args[i + 1] ? parseInt(args[i + 1], 10) : 7; })();
const DRY    = args.includes('--dry-run');
const VERB   = args.includes('--verbose');

const MAX_CONTENT_LEN = 200;   // per-memory content truncation
const MAX_PACK_LEN    = 800;   // per-context pack max chars

const DATA_DIR  = path.join(__dirname, '..', 'data');
const JSON_PATH = path.join(DATA_DIR, 'context-packs.json');

// ── Helpers ───────────────────────────────────────────────────────────
function truncate(str, max) {
  if (!str) return '';
  const clean = str.replace(/\n/g, ' ').trim();
  return clean.length <= max ? clean : clean.slice(0, max - 1) + '…';
}

function log(...a) { if (VERB) console.error('[context-pack-builder]', ...a); }

// ── Main ──────────────────────────────────────────────────────────────
async function main() {
  // 1. Fetch hot + warm memories from the last N days
  const { rows: memories } = await db.query(`
    SELECT id, type, content, context, tier, importance, tags, created_at
    FROM brainx_memories
    WHERE superseded_by IS NULL
      AND tier IN ('hot', 'warm')
      AND created_at > NOW() - $1::interval
    ORDER BY importance DESC, created_at DESC
  `, [`${DAYS} days`]);

  log(`Fetched ${memories.length} memories from last ${DAYS} days`);

  if (memories.length === 0) {
    console.log(JSON.stringify({ packs: [], count: 0, days: DAYS, message: 'No memories found' }));
    process.exit(0);
  }

  // 2. Group by context
  const groups = {};
  for (const m of memories) {
    const ctx = m.context || 'unknown';
    if (!groups[ctx]) groups[ctx] = [];
    groups[ctx].push(m);
  }

  log(`Grouped into ${Object.keys(groups).length} contexts: ${Object.keys(groups).join(', ')}`);

  // 3. Build packs
  const packs = [];

  for (const [ctx, mems] of Object.entries(groups)) {
    const avgImp = (mems.reduce((s, m) => s + (m.importance || 0), 0) / mems.length).toFixed(1);
    let header = `### ${ctx} (${mems.length} memories, avg importance ${avgImp})`;
    let lines  = [];

    for (const m of mems) {
      const line = `- [${m.type || 'note'}] ${truncate(m.content, MAX_CONTENT_LEN)}`;
      lines.push(line);
    }

    // Assemble and enforce MAX_PACK_LEN
    let pack = header + '\n' + lines.join('\n');
    if (pack.length > MAX_PACK_LEN) {
      // Keep header, trim lines until within budget
      let trimmed = header + '\n';
      for (const line of lines) {
        if ((trimmed + line + '\n').length > MAX_PACK_LEN - 20) {
          trimmed += `- ... (+${mems.length - lines.indexOf(line)} more)\n`;
          break;
        }
        trimmed += line + '\n';
      }
      pack = trimmed.trimEnd();
    }

    packs.push({
      context:     ctx,
      memoryCount: mems.length,
      avgImportance: parseFloat(avgImp),
      pack,
      generatedAt: new Date().toISOString(),
    });
  }

  // 4. Output
  const output = {
    packs,
    count:  packs.length,
    days:   DAYS,
    dryRun: DRY,
    generatedAt: new Date().toISOString(),
  };

  console.log(JSON.stringify(output, null, 2));

  if (DRY) {
    log('Dry run — skipping persistence');
    process.exit(0);
  }

  // 5. Persist — try table first, fall back to JSON file
  let usedTable = false;
  try {
    const { rows } = await db.query(
      "SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'brainx_context_packs')"
    );
    if (rows[0].exists) {
      await persistToTable(packs);
      usedTable = true;
      log('Saved packs to brainx_context_packs table');
    }
  } catch (err) {
    log('Table persistence failed, falling back to JSON:', err.message);
  }

  if (!usedTable) {
    await persistToJson(output);
    log(`Saved packs to ${JSON_PATH}`);
  }

  process.exit(0);
}

// ── Persistence: DB table ─────────────────────────────────────────────
async function persistToTable(packs) {
  for (const p of packs) {
    const id = `cp_${p.context.replace(/[^a-z0-9]/gi, '_')}_${Date.now()}`;
    await db.query(`
      INSERT INTO brainx_context_packs (id, data, created_at, updated_at)
      VALUES ($1, $2, NOW(), NOW())
    `, [id, JSON.stringify(p)]);
  }
}

// ── Persistence: JSON file fallback ───────────────────────────────────
async function persistToJson(output) {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }
  fs.writeFileSync(JSON_PATH, JSON.stringify(output, null, 2), 'utf-8');
}

// ── Run ───────────────────────────────────────────────────────────────
main().catch(err => {
  console.error('FATAL:', err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * BrainX V5 — Contradiction Detector (Phase 3.1)
 *
 * Detects semantically overlapping hot memories and marks older/shorter
 * ones as superseded by their newer/more-complete counterpart.
 *
 * Usage:
 *   node scripts/contradiction-detector.js [--top N] [--threshold N] [--dry-run] [--verbose]
 *
 * Options:
 *   --top N        Number of hot memories to analyze (default 30)
 *   --threshold N  Cosine similarity threshold (default 0.85)
 *   --dry-run      Report only, do not update the database
 *   --verbose      Print detailed pair analysis
 */

'use strict';

require('dotenv').config({ path: require('path').join(__dirname, '..', '.env') });
const db = require('../lib/db');

// ── CLI args ────────────────────────────────────────────────────────────────
function parseArgs() {
  const args = process.argv.slice(2);
  const opts = { top: 30, threshold: 0.85, dryRun: false, verbose: false };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--top':
        opts.top = parseInt(args[++i], 10) || 30;
        break;
      case '--threshold':
        opts.threshold = parseFloat(args[++i]) || 0.85;
        break;
      case '--dry-run':
        opts.dryRun = true;
        break;
      case '--verbose':
        opts.verbose = true;
        break;
    }
  }
  return opts;
}

// ── Main ────────────────────────────────────────────────────────────────────
async function main() {
  const opts = parseArgs();
  const startMs = Date.now();

  if (opts.verbose) {
    console.error(`[contradiction-detector] top=${opts.top} threshold=${opts.threshold} dryRun=${opts.dryRun}`);
  }

  // 1. Fetch top hot memories (not already superseded)
  const { rows: memories } = await db.query(`
    SELECT id, type, content, context, tier, importance, access_count, tags, created_at,
           length(content) AS content_len
    FROM brainx_memories
    WHERE superseded_by IS NULL
      AND tier = 'hot'
    ORDER BY access_count DESC NULLS LAST, importance DESC
    LIMIT $1
  `, [opts.top]);

  if (opts.verbose) {
    console.error(`[contradiction-detector] fetched ${memories.length} hot memories`);
  }

  if (memories.length < 2) {
    const result = { ok: true, pairsAnalyzed: 0, contradictionsFound: 0, superseded: [], complementary: 0, details: [] };
    console.log(JSON.stringify(result, null, 2));
    await db.pool.end();
    return;
  }

  // 2. Compute pairwise cosine similarity in one efficient query
  //    Build id list and fetch all similarities at once
  const ids = memories.map(m => m.id);
  const idIndex = Object.fromEntries(memories.map((m, i) => [m.id, i]));

  // Generate pairs
  const pairs = [];
  for (let i = 0; i < memories.length; i++) {
    for (let j = i + 1; j < memories.length; j++) {
      pairs.push([memories[i], memories[j]]);
    }
  }

  if (opts.verbose) {
    console.error(`[contradiction-detector] analyzing ${pairs.length} pairs`);
  }

  // Batch-fetch similarities for all pairs using a single query with unnest
  const idPairsA = pairs.map(p => p[0].id);
  const idPairsB = pairs.map(p => p[1].id);

  const { rows: simRows } = await db.query(`
    SELECT a_id, b_id, 1 - (ma.embedding <=> mb.embedding) AS similarity
    FROM unnest($1::text[], $2::text[]) AS t(a_id, b_id)
    JOIN brainx_memories ma ON ma.id = t.a_id
    JOIN brainx_memories mb ON mb.id = t.b_id
  `, [idPairsA, idPairsB]);

  // Index similarities by pair
  const simMap = new Map();
  for (const row of simRows) {
    simMap.set(`${row.a_id}|${row.b_id}`, parseFloat(row.similarity));
  }

  // 3. Analyze high-similarity pairs
  const supersededIds = [];
  let complementary = 0;
  const details = [];

  for (const [memA, memB] of pairs) {
    const sim = simMap.get(`${memA.id}|${memB.id}`);
    if (sim === undefined || sim < opts.threshold) continue;

    // Different contexts → complementary, not contradiction
    if (memA.context && memB.context && memA.context !== memB.context) {
      complementary++;
      if (opts.verbose) {
        console.error(`  [complementary] ${memA.id} <> ${memB.id} sim=${sim.toFixed(3)} contexts differ (${memA.context} vs ${memB.context})`);
      }
      details.push({
        action: 'complementary',
        ids: [memA.id, memB.id],
        similarity: parseFloat(sim.toFixed(4)),
        reason: `different contexts: "${memA.context}" vs "${memB.context}"`
      });
      continue;
    }

    // Determine which to keep: prefer newer + longer content
    const aDate = new Date(memA.created_at);
    const bDate = new Date(memB.created_at);
    const aLen = memA.content_len;
    const bLen = memB.content_len;

    // Size difference threshold: 10% — "same size" if within 10%
    const sizeDiffRatio = Math.abs(aLen - bLen) / Math.max(aLen, bLen, 1);
    const sameSize = sizeDiffRatio < 0.10;

    let keepMem, supersedeMem, reason;

    if (sameSize) {
      // Same size → keep higher importance
      if (memA.importance >= memB.importance) {
        keepMem = memA;
        supersedeMem = memB;
      } else {
        keepMem = memB;
        supersedeMem = memA;
      }
      reason = `same size (${aLen} vs ${bLen}), kept higher importance (${keepMem.importance} >= ${supersedeMem.importance})`;
    } else {
      // Different size → prefer newer AND longer
      const aIsNewer = aDate >= bDate;
      const aIsLonger = aLen > bLen;
      const bIsNewer = bDate >= aDate;
      const bIsLonger = bLen > aLen;

      if (aIsNewer && aIsLonger) {
        keepMem = memA;
        supersedeMem = memB;
        reason = `A is newer (${aDate.toISOString().slice(0, 10)}) and longer (${aLen} > ${bLen})`;
      } else if (bIsNewer && bIsLonger) {
        keepMem = memB;
        supersedeMem = memA;
        reason = `B is newer (${bDate.toISOString().slice(0, 10)}) and longer (${bLen} > ${aLen})`;
      } else {
        // Conflict: newer but shorter — keep the longer one (more complete)
        if (aIsLonger) {
          keepMem = memA;
          supersedeMem = memB;
          reason = `A is longer (${aLen} > ${bLen}) though B is newer; keeping more complete`;
        } else {
          keepMem = memB;
          supersedeMem = memA;
          reason = `B is longer (${bLen} > ${aLen}) though A is newer; keeping more complete`;
        }
      }
    }

    if (opts.verbose) {
      console.error(`  [supersede] ${supersedeMem.id} → superseded by ${keepMem.id} sim=${sim.toFixed(3)} ${reason}`);
    }

    // Skip if already superseded by a previous pair in this run
    if (supersededIds.includes(supersedeMem.id)) {
      if (opts.verbose) {
        console.error(`    [skip] ${supersedeMem.id} already superseded in this run`);
      }
      continue;
    }

    // Merge tags from superseded into keeper
    const mergedTags = [...new Set([...(keepMem.tags || []), ...(supersedeMem.tags || []), 'dedup_contradiction'])];

    if (!opts.dryRun) {
      // Mark superseded
      await db.query(
        `UPDATE brainx_memories SET superseded_by = $1 WHERE id = $2`,
        [keepMem.id, supersedeMem.id]
      );

      // Merge tags into keeper
      await db.query(
        `UPDATE brainx_memories SET tags = $1 WHERE id = $2`,
        [mergedTags, keepMem.id]
      );
    }

    supersededIds.push(supersedeMem.id);
    details.push({
      action: 'superseded',
      kept: keepMem.id,
      superseded: supersedeMem.id,
      similarity: parseFloat(sim.toFixed(4)),
      reason
    });
  }

  const durationMs = Date.now() - startMs;

  // 4. Log to brainx_query_log (if constraint allows; gracefully skip if not)
  try {
    await db.query(
      `INSERT INTO brainx_query_log (query_hash, query_kind, results_count, duration_ms)
       VALUES ($1, 'contradiction_check', $2, $3)`,
      [
        `contradiction_${new Date().toISOString().slice(0, 10)}`,
        supersededIds.length,
        durationMs
      ]
    );
  } catch (logErr) {
    // CHECK constraint may not include 'contradiction_check' — safe to skip
    if (opts.verbose) {
      console.error(`[contradiction-detector] query_log insert skipped: ${logErr.message}`);
    }
  }

  // 5. Output result
  const result = {
    ok: true,
    dryRun: opts.dryRun,
    pairsAnalyzed: pairs.length,
    contradictionsFound: supersededIds.length,
    superseded: supersededIds,
    complementary,
    durationMs,
    details
  };

  console.log(JSON.stringify(result, null, 2));
  await db.pool.end();
}

main().catch(async (err) => {
  console.error(err);
  try { await db.pool.end(); } catch (_) {}
  process.exit(1);
});

#!/usr/bin/env node
/**
 * cross-agent-learning.js — BrainX V5 Phase 4.2
 *
 * Propagates high-importance learnings and gotchas from individual agents
 * to the global context so ALL agents benefit from shared discoveries.
 *
 * Usage:
 *   node scripts/cross-agent-learning.js [--hours N] [--dry-run] [--verbose] [--max-shares N]
 */

'use strict';

const path = require('path');
const crypto = require('crypto');

// ── Bootstrap ───────────────────────────────────────────────────────────
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });
const db = require(path.join(__dirname, '..', 'lib', 'db'));
const rag = require(path.join(__dirname, '..', 'lib', 'openai-rag'));

// ── Args ────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);

function flag(name) {
  return args.includes(`--${name}`);
}
function option(name, fallback) {
  const idx = args.indexOf(`--${name}`);
  if (idx === -1 || idx + 1 >= args.length) return fallback;
  return args[idx + 1];
}

const HOURS = parseInt(option('hours', '24'), 10);
const DRY_RUN = flag('dry-run');
const VERBOSE = flag('verbose');
const MAX_SHARES = parseInt(option('max-shares', '10'), 10);

function log(...a) { if (VERBOSE) console.error('[cross-agent]', ...a); }

// ── Sleep helper ────────────────────────────────────────────────────────
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ── Main ────────────────────────────────────────────────────────────────
async function main() {
  const result = {
    ok: true,
    candidatesFound: 0,
    alreadyShared: 0,
    newlyShared: 0,
    skippedMaxShares: 0,
    bySourceAgent: {},
    errors: [],
  };

  try {
    // 1. Find recent high-importance learnings/gotchas from specific agents
    log(`Searching for learnings/gotchas/decisions/facts in last ${HOURS}h with importance >= 5...`);

    const candidates = await db.query(
      `SELECT id, type, content, context, tier, importance, tags, embedding, created_at
       FROM brainx_memories
       WHERE superseded_by IS NULL
         AND (
           (type IN ('learning', 'gotcha') AND importance >= 5)
           OR (type IN ('decision', 'fact') AND importance >= 6)
         )
         AND context LIKE 'agent:%'
         AND context != 'global'
         AND created_at > NOW() - make_interval(hours => $1)
       ORDER BY importance DESC, created_at DESC
       LIMIT 20`,
      [HOURS]
    );

    result.candidatesFound = candidates.rows.length;
    log(`Found ${result.candidatesFound} candidates`);

    if (result.candidatesFound === 0) {
      console.log(JSON.stringify(result));
      return;
    }

    // 2. For each candidate, check if a global copy already exists
    for (const mem of candidates.rows) {
      if (result.newlyShared >= MAX_SHARES) {
        result.skippedMaxShares++;
        log(`Max shares (${MAX_SHARES}) reached, skipping ${mem.id}`);
        continue;
      }

      // Extract agent name from context (e.g. "agent:coder" → "coder")
      const agentName = mem.context.replace(/^agent:/, '');

      // Check for existing global copy using embedding similarity
      // The embedding column is already a vector — pass it directly
      const existing = await db.query(
        `SELECT id FROM brainx_memories
         WHERE context = 'global'
           AND superseded_by IS NULL
           AND 1 - (embedding <=> $1) > 0.90
         LIMIT 1`,
        [mem.embedding]
      );

      if (existing.rows.length > 0) {
        result.alreadyShared++;
        log(`Already shared: ${mem.id} (matched global ${existing.rows[0].id})`);
        continue;
      }

      // 3. Create global copy
      const globalId = `m_global_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
      const globalContent = `[Shared from ${mem.context}] ${mem.content}`;
      const originalTags = Array.isArray(mem.tags) ? mem.tags : [];
      const globalTags = [...originalTags, 'cross-agent', `origin:${mem.context}`];
      const globalImportance = Math.max((mem.importance || 5) - 1, 5);

      log(`Sharing: ${mem.id} → ${globalId} (${mem.type}, importance ${globalImportance})`);

      if (!DRY_RUN) {
        try {
          await rag.storeMemory({
            id: globalId,
            type: mem.type,
            content: globalContent,
            context: 'global',
            tier: 'warm',
            importance: globalImportance,
            tags: globalTags,
          });
          log(`Stored global memory: ${globalId}`);
        } catch (err) {
          result.errors.push({ memoryId: mem.id, error: err.message });
          log(`Error storing ${globalId}: ${err.message}`);
          continue;
        }

        // Rate limit: 300ms between embedding API calls
        await sleep(300);
      } else {
        log(`[DRY-RUN] Would share: ${mem.id} → ${globalId}`);
      }

      result.newlyShared++;
      result.bySourceAgent[agentName] = (result.bySourceAgent[agentName] || 0) + 1;
    }

    // Report
    if (DRY_RUN) {
      log('[DRY-RUN] No memories were actually stored.');
    }

    console.log(JSON.stringify(result));
  } catch (err) {
    result.ok = false;
    result.errors.push({ error: err.message, stack: err.stack });
    console.log(JSON.stringify(result));
    process.exitCode = 1;
  } finally {
    await db.pool.end();
  }
}

main();

#!/usr/bin/env node

require('dotenv').config({ path: require('path').join(__dirname, '..', '.env') });

const db = require('../lib/db');

async function main() {
  const dryRun = process.argv.includes('--dry-run') || String(process.env.DEDUP_DRY_RUN || 'false') === 'true';

  const dups = await db.query(`
    WITH dups AS (
      SELECT md5(coalesce(type,'')||'|'||coalesce(content,'')||'|'||coalesce(context,'')||'|'||coalesce(agent,'')) as fp,
             array_agg(id ORDER BY created_at ASC) as ids
      FROM brainx_memories
      WHERE superseded_by IS NULL
      GROUP BY fp
      HAVING count(*) > 1
    ), pairs AS (
      SELECT fp, ids[1] as keep_id, unnest(ids[2:]) as sup_id
      FROM dups
    )
    SELECT * FROM pairs;
  `);

  if (dryRun) {
    console.log(JSON.stringify({ ok: true, dryRun: true, pairs: dups.rows.length, sample: dups.rows.slice(0, 10) }, null, 2));
    return;
  }

  const res = await db.query(`
    WITH dups AS (
      SELECT md5(coalesce(type,'')||'|'||coalesce(content,'')||'|'||coalesce(context,'')||'|'||coalesce(agent,'')) as fp,
             array_agg(id ORDER BY created_at ASC) as ids
      FROM brainx_memories
      WHERE superseded_by IS NULL
      GROUP BY fp
      HAVING count(*) > 1
    ), pairs AS (
      SELECT fp, ids[1] as keep_id, unnest(ids[2:]) as sup_id
      FROM dups
    )
    UPDATE brainx_memories m
    SET superseded_by = p.keep_id,
        tags = CASE
          WHEN NOT (m.tags @> ARRAY['dedup_superseded']) THEN m.tags || ARRAY['dedup_superseded']
          ELSE m.tags
        END
    FROM pairs p
    WHERE m.id = p.sup_id;
  `);

