async function testMetricsOutput() {
  const io = makeIo();
  let call = 0;
  const db = {
    async query(_sql, _params) {
      call += 1;
      const responses = [
        { rows: [{ key: 'pending', count: 2 }] },
        { rows: [{ key: 'learning', count: 1 }] },
        { rows: [{ key: 'warm', count: 2 }] },
